import itertools, json
jobs='ABCDE'
slots=[[0,1,4,11,3],[2,3,3,2,5],[4,8,2,10,8],[3,2,11,3,4],[10,6,10,10,4]]
trans=[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]
idx={j:i for i,j in enumerate(jobs)}
perms=[''.join(p) for p in itertools.permutations(jobs) if p.index('A')<p.index('D')]
def nominal(p):
    return sum(slots[idx[j]][s] for s,j in enumerate(p))+sum(trans[idx[a]][idx[b]] for a,b in zip(p,p[1:]))
def incident(p,event):
    pos={j:p.index(j)+1 for j in jobs}
    if event=='rain':
        return None if pos['D']==1 or pos['A']==1 else nominal(p)+6*max(0,pos['C']-1)
    if event=='road':
        return None if pos['C']==4 or pos['E']==2 else nominal(p)+6*max(0,pos['D']-3)
    return None if pos['A']==1 or pos['B']==1 else nominal(p)+10*max(0,pos['E']-2)
def neighbors(p):
    yield p,0
    for i,j in itertools.combinations(range(5),2):
        q=list(p); q[i],q[j]=q[j],q[i]; q=''.join(q)
        if q.index('A')<q.index('D'): yield q,1
records=[]
for p in perms:
    repairs={}; costs={}
    for event in ['rain','road','lift']:
        options=[(incident(q,event)+fee,q) for q,fee in neighbors(p) if incident(q,event) is not None]
        if not options: break
        costs[event],repairs[event]=min(options)
    else:
        records.append((nominal(p)+max(costs.values()),p,repairs,costs))
records.sort()
score,p,repairs,costs=records[0]
# Independent neighborhood test: two permutations are a single exchange apart
# precisely when their Hamming distance is two; equal permutations cost zero.
independent=[]
for pub in perms:
    vals=[]
    for event in ['rain','road','lift']:
        options=[]
        for final in perms:
            d=sum(a!=b for a,b in zip(pub,final))
            if d not in (0,2): continue
            c=incident(final,event)
            if c is not None: options.append(c+(d==2))
        if not options: break
        vals.append(min(options))
    else: independent.append((nominal(pub)+max(vals),pub))
assert sorted(independent)==sorted((r[0],r[1]) for r in records)
result={'roster':p,'score':score,'repairs':repairs,'repair_costs':costs,'feasible_count':len(records),'next_score':min(r[0] for r in records if r[0]>score)}
payload=json.dumps(result)
assert json.loads(payload)==result
print(payload)
print('Verification:',len(perms),'precedence-valid publications; published nominal cost',nominal(p),'; all enumeration results independently matched.')

