import itertools,json
pub='AECBD'
jobs='ABCDE'
slot={'A':[0,1,4,11,3],'B':[2,3,3,2,5],'C':[4,8,2,10,8],'D':[3,2,11,3,4],'E':[10,6,10,10,4]}
t=[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]
def dist(q):
    perm=[pub.index(j) for j in q]
    seen=set(); cycles=0
    for i in range(5):
        if i not in seen:
            cycles+=1
            while i not in seen:
                seen.add(i); i=perm[i]
    return 5-cycles
def cost(q,d):
    return sum(slot[j][i] for i,j in enumerate(q))+sum(t[jobs.index(a)][jobs.index(b)] for a,b in zip(q,q[1:]))+6*q.index('C')+d+(4 if d==2 else 0)
classes={d:[] for d in range(3)}
for p in itertools.permutations(jobs):
    q=''.join(p); d=dist(q)
    if d>2 or q.index('A')>q.index('D') or q[0] in 'AD' or q[3]=='B': continue
    classes[d].append((cost(q,d),q))
best=min(x for cl in classes.values() for x in cl)
# Verify minimum distances by breadth-first search over all pair exchanges.
distance={pub:0}; frontier=[pub]
for depth in (1,2):
    nxt=[]
    for p in frontier:
        for i,j in itertools.combinations(range(5),2):
            q=list(p); q[i],q[j]=q[j],q[i]; q=''.join(q)
            if q not in distance: distance[q]=depth; nxt.append(q)
    frontier=nxt
assert all(dist(q)==d for q,d in distance.items())
assert {q for cl in classes.values() for c,q in cl}=={q for q in distance if q.index('A')<q.index('D') and q[0] not in 'AD' and q[3]!='B'}
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(cl)[0] if cl else None for d,cl in classes.items()},'feasible_by_swaps':{str(d):len(cl) for d,cl in classes.items()}}))
print('Verified by cycle distance and breadth-first pair-exchange enumeration.')

